import Foundation

/// Each command to its handler, with its arguments read and checked first.
enum Dispatch {
    static func run(_ command: Command, _ input: AgentInput, _ kit: CommandKit) async throws -> [Product] {
        switch command {
        case .tip: return try await TipHandler.run(TipArguments(from: input), kit)
        case .split: return try await SplitHandler.run(SplitArguments(from: input), kit)
        }
    }
}
